const crypto = require('crypto');

const HMAC_SECRET   = $env['N8N_WEBHOOK_HMAC_SECRET'];
const MAX_SKEW_SECS = 300;

const item    = $input.first();
const headers = item.json.headers || {};

const sigHeader = headers['x-eduai-signature-256']   || '';
const tsHeader  = headers['x-eduai-timestamp']       || '';
const idempKey  = headers['x-eduai-idempotency-key'] || '';

const nowSecs = Math.floor(Date.now() / 1000);
const tsSecs  = parseInt(tsHeader, 10);
if (isNaN(tsSecs) || Math.abs(nowSecs - tsSecs) > MAX_SKEW_SECS) {
  throw new Error(`Timestamp rejected: skew=${nowSecs - tsSecs}s`);
}

const rawBody  = item.json.rawBody || JSON.stringify(item.json.body);
const expected = 'sha256=' + crypto.createHmac('sha256', HMAC_SECRET).update(rawBody, 'utf8').digest('hex');
const sigBuf = Buffer.from(sigHeader);
const expBuf = Buffer.from(expected);
if (sigBuf.length !== expBuf.length || !crypto.timingSafeEqual(sigBuf, expBuf)) {
  throw new Error('Signature verification failed');
}

const body = typeof rawBody === 'string' ? JSON.parse(rawBody) : rawBody;
return [{ json: { ...body, _idempotency_key: idempKey, _verified: true } }];

// ============================================================
// Retry State Manager
//
// Uses workflow static data to track retry attempts per file_id.
// Each incoming failure event increments the counter.
// After MAX_ATTEMPTS the job is routed to the dead-letter handler.
//
// Static data survives across executions for this workflow instance.
// For a clustered n8n deployment, replace with a shared Redis counter
// via HTTP Request to a sidecar or directly via a Redis node.
// ============================================================

const MAX_ATTEMPTS = 3;
const RETRY_WINDOW_MS = 30 * 60 * 1000; // reset counter after 30 min of silence

const item    = $input.first();
const payload = item.json.payload || {};

const fileId       = payload.file_id       || '';
const userId       = payload.user_id       || '';
const role         = payload.role          || '';
const submissionId = payload.submission_id || '';
const failureReasons = payload.failure_reasons || [];
const failureCode  = payload.failure_code  || 'unknown';
const pipeline     = payload.pipeline      || 'phase12_langgraph';
const graphName    = payload.graph_name    || '';
const executionId  = payload.execution_id  || '';

if (!fileId || !userId) {
  throw new Error('Malformed payload: file_id and user_id are required');
}

// Retrieve retry state
const sd = $getWorkflowStaticData('global');
if (!sd.retryState) sd.retryState = {};

const key = `${fileId}::${submissionId}`;
const now = Date.now();

if (!sd.retryState[key] || (now - sd.retryState[key].last_attempt) > RETRY_WINDOW_MS) {
  // First failure or window expired — reset counter
  sd.retryState[key] = { attempts: 0, first_failure: now, last_attempt: now };
}

sd.retryState[key].attempts    += 1;
sd.retryState[key].last_attempt = now;

const attempt = sd.retryState[key].attempts;
const shouldRetry = attempt <= MAX_ATTEMPTS;

// Evict stale keys (older than 2 × window) to bound memory
Object.keys(sd.retryState).forEach(k => {
  if ((now - sd.retryState[k].last_attempt) > RETRY_WINDOW_MS * 2) {
    delete sd.retryState[k];
  }
});

return [{
  json: {
    event_id:       item.json.event_id,
    correlation_id: item.json.correlation_id,
    file_id:        fileId,
    user_id:        userId,
    role,
    submission_id:  submissionId,
    failure_reasons: failureReasons,
    failure_code:   failureCode,
    pipeline,
    graph_name:     graphName,
    execution_id:   executionId,
    attempt,
    max_attempts:   MAX_ATTEMPTS,
    should_retry:   shouldRetry,
  }
}];

// Exponential back-off before retry dispatch
// attempt 1 → 5s, attempt 2 → 15s, attempt 3 → 45s
const item    = $input.first();
const attempt = item.json.attempt || 1;
const delayMs = Math.min(5000 * Math.pow(3, attempt - 1), 60000);

console.log(JSON.stringify({
  level:   'info',
  message: 'pipeline_retry_scheduled',
  file_id: item.json.file_id,
  attempt,
  delay_ms: delayMs,
  correlation_id: item.json.correlation_id,
}));

// n8n does not have a native sleep; use the Wait node in real workflows.
// Here we pass delay_ms downstream to document the intended back-off.
return [{ json: { ...item.json, retry_delay_ms: delayMs } }];

const item = $input.first();
console.log(JSON.stringify({
  level: 'info',
  message: 'pipeline_retry_succeeded',
  file_id:        item.json.file_id,
  attempt:        item.json.attempt,
  correlation_id: item.json.correlation_id,
}));
return [{ json: { status: 'retry_succeeded', ...item.json } }];

// ============================================================
// Dead-Letter Handler
//
// Triggered when:
//   a) max retry attempts exceeded (should_retry = false), OR
//   b) backend returned non-2xx on the final retry attempt.
//
// Actions (customize for your stack):
//   1. Emit a structured dead-letter log entry.
//   2. POST to an alerting endpoint (PagerDuty, Slack, etc.).
//   3. Insert a record into Supabase dead_letter_events table
//      via HTTP Request node so human review can be triggered.
//
// The job is NOT retried again — it requires manual intervention.
// ============================================================

const item = $input.first();

const dlqRecord = {
  id:              `dlq-${item.json.event_id || item.json.correlation_id}`,
  created_at:      new Date().toISOString(),
  file_id:         item.json.file_id,
  user_id:         item.json.user_id,
  role:            item.json.role,
  submission_id:   item.json.submission_id,
  failure_reasons: item.json.failure_reasons,
  failure_code:    item.json.failure_code,
  pipeline:        item.json.pipeline,
  graph_name:      item.json.graph_name,
  execution_id:    item.json.execution_id,
  attempts:        item.json.attempt || item.json.max_attempts,
  max_attempts:    item.json.max_attempts,
  correlation_id:  item.json.correlation_id,
  event_id:        item.json.event_id,
  status:          'dead_lettered',
  requires_review: true,
};

console.log(JSON.stringify({ level: 'error', message: 'pipeline_dead_lettered', ...dlqRecord }));

return [{ json: { dlq_record: dlqRecord } }];
